from typing import *

from collections import *

def correct_bracketing(brackets: str) -> bool:
    balance = 0
    for char in brackets:
        if char == '<':
            balance += 1
        elif char == '>':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

from math import sqrt

def largest_prime_factor(n: int) -> int:
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    def is_prime(num: int) -> bool:
        if num <= 1:
            return False
        for i in range(2, int(sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    largest = -1
    # Check for number of 2s that divide n
    while n % 2 == 0:
        largest = 2
        n //= 2

    # n must be odd at this point, so a skip of 2 (i.e., i = i + 2) can be used
    for i in range(3, int(sqrt(n)) + 1, 2):
        # While i divides n, store i and divide n
        while n % i == 0:
            largest = i
            n //= i

    # This condition is to check if n is a prime number greater than 2
    if n > 2:
        largest = n

    return largest

import math

def is_simple_power(x, n):
    if x == 1:
        return True
    if n <= 1 or x % n != 0:
        return False
    log_value = math.log(x, n)
    return log_value.is_integer()

def decimal_to_binary(decimal):
    """Converts a decimal number to its binary representation as a string, with 'db' at the start and end."""
    if decimal == 0:
        return "db0db"

    binary_str = ""
    while decimal > 0:
        remainder = decimal % 2
        binary_str = str(remainder) + binary_str
        decimal = decimal // 2

    return "db" + binary_str + "db"

import math

def prime_length(string):
    """Write a function that takes a string and returns True if the string
    length is a prime number or False otherwise
    Examples
    prime_length('Hello') == True
    prime_length('abcdcba') == True
    prime_length('kittens') == True
    prime_length('orange') == False
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    return is_prime(len(string))

def anti_shuffle(s):
    def sort_word(word):
        return ''.join(sorted(word))

    # Split the string into words and spaces
    words = s.split()

    # Sort each word
    sorted_words = [sort_word(word) for word in words]

    # Join the sorted words back with spaces
    return ' '.join(sorted_words)

def encrypt(s):
    def rotate_char(c):
        if c.isalpha():
            start = ord('a') if c.islower() else ord('A')
            return chr((ord(c) - start + 2 * 2) % 26 + start)
        return c

    return ''.join(rotate_char(c) for c in s)

