from typing import List

def max_fill(grid: List[List[int]], capacity: int) -> int:
    total_water = sum(row.count(1) for row in grid)
    return math.ceil(total_water / capacity)

def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels and word[i-1] not in vowels and word[i+1] not in vowels:
            return word[i]
    return ""

from datetime import datetime

def valid_date(date):
    """You have to write a function which validates a given date string and
    returns True if the date is valid otherwise False.
    The date is valid if all of the following rules are satisfied:
    1. The date string is not empty.
    2. The number of days is not less than 1 or higher than 31 days for months 1,3,5,7,8,10,12. And the number of days is not less than 1 or higher than 30 days for months 4,6,9,11. And, the number of days is not less than 1 or higher than 29 for the month 2.
    3. The months should not be less than 1 or higher than 12.
    4. The date should be in the format: mm-dd-yyyy

    for example: 
    valid_date('03-11-2000') => True

    valid_date('15-01-2012') => False

    valid_date('04-0-2040') => False

    valid_date('06-04-2020') => True

    valid_date('06/04/2020') => False
    """
    # Check if the date string is empty
    if not date:
        return False

    # Check if the date string matches the required format
    try:
        datetime.strptime(date, '%m-%d-%Y')
    except ValueError:
        return False

    # Extract month and day from the date string
    month, day, year = map(int, date.split('-'))

    # Check if the month is valid
    if month < 1 or month > 12:
        return False

    # Check if the day is valid based on the month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    else:  # month is 2 (February)
        if day < 1 or day > 29:
            return False

    return True

def prod_signs(arr):
    if not arr:
        return None

    sign_product = 1
    magnitude_sum = 0

    for num in arr:
        if num == 0:
            return 0
        sign_product *= (1 if num > 0 else -1)
        magnitude_sum += abs(num)

    return sign_product * magnitude_sum
